// Exhaust surviving opposite-side pairs via bitset joins. Stdout lists unexcluded assignments.
#[allow(dead_code)]mod engine{include!("ramsey310_bulk_side.rs");
include!("ramsey310_s3_score.rs");
fn weight(row:&[u32;3],q:u32)->usize{row.iter().filter(|&&s|s&q!=0).count()}
fn and(m:&mut[u64],n:&[u64]){for(x,y)in m.iter_mut().zip(n){*x &= y}}
fn work(){let args:Vec<_>=env::args().collect();let txt=fs::read_to_string(&args[1]).unwrap();let mut it=txt.split_whitespace().map(|x|x.parse::<u32>().unwrap());let mut read=||{let n=it.next().unwrap();(0..n).map(|_|it.next().unwrap()).collect::<Vec<_>>()};let a=read();let _=read();let six=read();let s=read();let n=s.len();assert!(n<=768);let src=fs::read_to_string(&args[2]).unwrap();let mut rows=vec![];let mut ids=vec![];let id:HashMap<u32,usize>=s.iter().copied().enumerate().map(|(j,x)|(x,j)).collect();for line in src.lines(){let y:Vec<u32>=line.split_whitespace().map(|x|x.parse().unwrap()).collect();let e=[y[0],y[1],y[2]];ids.push(e.map(|x|id[&x]));rows.push(e)}let t=rows.len();let w=t.div_ceil(64);
let mut inc=[B::default();26];let mut full=B::default();for(i,&x)in s.iter().enumerate(){full.put(i);for v in 0..26{if x>>v&1!=0{inc[v].put(i)}}}let misses=|x:u32|{let mut b=full;for v in 0..26{if x>>v&1!=0{b.sub(inc[v])}}b};let ms:Vec<_>=s.iter().copied().map(misses).collect();let m6:Vec<_>=six.iter().copied().map(misses).collect();let mut pair=vec![full;n*n];for i in 0..n{for j in 0..i{let mut m=full;ms[i].and(ms[j]).each(|k|m.sub(ms[k]));pair[i*n+j]=m;pair[j*n+i]=m}}
let mut d6=vec![vec![0u64;six.len().div_ceil(64)];n];for(i,&x)in s.iter().enumerate(){for(j,&y)in six.iter().enumerate(){if x&y==0{d6[i][j/64]|=1<<(j%64)}}}
// Per (left support, fixed right position) index disjoint right-side triples.
let mut dis=vec![vec![0u64;w];3*n];for(i,&x)in s.iter().enumerate(){for(j,r)in rows.iter().enumerate(){for h in 0..3{if x&r[h]==0{dis[3*i+h][j/64]|=1<<(j%64)}}}}
// Vertex total exclusive-degree upper bound and edge exclusive-coverage lower bound.
let mut restrictions=vec![];for v in 0..26{restrictions.push((1u32<<v,(8-a[v].count_ones()).min(3) as i32,false));for u in 0..v{if a[v]>>u&1!=0{let min=12-(a[v].count_ones()+a[u].count_ones())as i32;if min>0{restrictions.push((1<<v|1<<u,min,true))}}}}
let mut index=vec![vec![vec![0u64;w];4];restrictions.len()];for(h,&(q,b,lower))in restrictions.iter().enumerate(){for(j,row)in rows.iter().enumerate(){let r=weight(row,q)as i32;for l in 0..4{if if lower{r+l as i32>=b}else{r+l as i32<=b}{index[h][l][j/64]|=1<<(j%64)}}}}
let audit=env::var_os("RAMSEY_S3_AUDIT").is_some();let(mut s3early,mut s3final)=(0u64,0u64);let mut joined=0u64;let mut pairlive=0u64;let mut passed=0u64;let end=args.get(3).map(|x|x.parse().unwrap()).unwrap_or(t).min(t);for i in 0..end{let l=rows[i];let mut allowed=vec![!0u64;i.div_ceil(64)];if i%64!=0{*allowed.last_mut().unwrap()=(1u64<<(i%64))-1};for(h,&(q,_,_))in restrictions.iter().enumerate(){and(&mut allowed,&index[h][weight(&l,q)])}let il=ids[i];for perm in [[0,1,2],[0,2,1],[1,0,2],[1,2,0],[2,0,1],[2,1,0]]{let(d0,d1,d2)=(&dis[il[0]*3+perm[0]],&dis[il[1]*3+perm[1]],&dis[il[2]*3+perm[2]]);for (b,&ok)in allowed.iter().enumerate(){let mut h=ok&d0[b]&d1[b]&d2[b];while h!=0{let j=64*b+h.trailing_zeros()as usize;h&=h-1;let ir=perm.map(|k|ids[j][k]);if ir.iter().any(|y|il.contains(y)){continue}joined+=1;let mut p=full;for x in 0..3{for y in 0..3{if x!=y{p=p.and(pair[il[x]*n+ir[y]])}}}if p.count()<6{continue}let r=ir.map(|x|s[x]);let mut ones=0;let mut needs=[0;26];for v in 0..26{needs[v]=9-a[v].count_ones()-weight(&l,1<<v)as u32-weight(&r,1<<v)as u32;if needs[v]==1{ones|=1u32<<v}}if (0..26).any(|v|p.and(inc[v]).count()<needs[v]){continue}pairlive+=1;if audit{if let Some(cert)=s3_cut(&a,&s,p,l,r,needs){if s3early==0{eprintln!("first early cut {l:?} {r:?} {cert:?}")}s3early+=1}}
let mut bad=false;for mix in 0..8{let z=[0,1,2].map(|k|if mix>>k&1==0{il[k]}else{ir[k]});let u=s[z[0]]|s[z[1]]|s[z[2]];let mut m=ones&!u;if m.count_ones()>6{bad=true;break}while m!=0{let v=m.trailing_zeros()as usize;m&=m-1;let mut mm=m;while mm!=0{let y=mm.trailing_zeros()as usize;mm&=mm-1;p.sub(inc[v].and(inc[y]))}}if mix!=0&&mix!=7{for w in 0..d6[0].len(){let mut m=d6[z[0]][w]&d6[z[1]][w]&d6[z[2]][w];while m!=0{p.sub(m6[64*w+m.trailing_zeros()as usize]);m&=m-1}}}if p.count()<6{bad=true;break}}if bad||(0..26).any(|v|p.and(inc[v]).count()<needs[v]){continue}passed+=1;if audit{if let Some(cert)=s3_cut(&a,&s,p,l,r,needs){if s3final==0{eprintln!("first final cut {l:?} {r:?} {cert:?}")}s3final+=1}}println!("{} {} {} {} {} {}",l[0],l[1],l[2],r[0],r[1],r[2]);}}}}if audit{eprintln!("frozen S3 cuts at seven_supply {s3early}/{pairlive}, at joint_supply {s3final}/{passed}")}eprintln!("sides {end}/{t} matched_after_capacity {joined} after_seven_supply {pairlive} after_joint_supply {passed}")}
pub fn start(){work()}}
fn main(){engine::start()}
